const $ = (selector, root = document) => root.querySelector(selector);
const app = $('#app');
const state = { page:'home', query:'', category:'Все', guideId:null, sessionId:null, step:0, checked:new Set(), editingId:null, toast:null, busy:false, aiTopic:'', aiError:'', completed:false };
let db = { guides:[], events:[], author:{name:'Автор'} };

const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icon = (name, size=20) => {
  const paths = {
    grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    book:'<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v17H6.5A2.5 2.5 0 0 1 4 17.5z"/><path d="M4 17.5A2.5 2.5 0 0 1 6.5 15H20M8 7h7M8 10h8"/>',
    chart:'<path d="M4 19V5M4 19h17"/><path d="m7 15 4-4 3 2 6-7"/><path d="M17 6h3v3"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/>',
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    back:'<path d="M19 12H5m6 6-6-6 6-6"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    sparkle:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z"/><path d="m19 16 .8 2.2L22 19l-2.2.8L19 22l-.8-2.2L16 19l2.2-.8z"/>',
    close:'<path d="m6 6 12 12M18 6 6 18"/>',
    edit:'<path d="m15 5 4 4M4 20l4-.8L19 8a2.1 2.1 0 0 0-3-3L5 16z"/>',
    chevron:'<path d="m9 18 6-6-6-6"/>',
    menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
    external:'<path d="M14 4h6v6m0-6-9 9"/><path d="M18 13v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h5"/>',
    warning:'<path d="m10.3 4.4-7.2 13A1.8 1.8 0 0 0 4.7 20h14.6a1.8 1.8 0 0 0 1.6-2.6l-7.2-13a1.9 1.9 0 0 0-3.4 0Z"/><path d="M12 9v4m0 3h.01"/>',
    bars:'<path d="M4 19V5m0 14h17"/><rect x="7" y="12" width="3" height="4" rx=".5"/><rect x="13" y="8" width="3" height="8" rx=".5"/><rect x="19" y="4" width="3" height="12" rx=".5"/>',
  };
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
};
const eventCount = (type, guideId) => db.events.filter(item => item.type===type && (!guideId || item.guideId===guideId)).length;
const weeklyStarts = guideIds => Array.from({length:12},(_,index)=>{const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-(11-index)*7);const end=new Date(start);end.setDate(end.getDate()+7);return db.events.filter(event=>event.type==='started'&&guideIds.includes(event.guideId)&&new Date(event.at)>=start&&new Date(event.at)<end).length;});
const stopCounts = guide => {const starts=db.events.filter(event=>event.type==='started'&&event.guideId===guide.id);const events=db.events.filter(event=>event.guideId===guide.id);const counts=guide.steps.map(()=>0);for(const start of starts){const session=start.sessionId||start.id;const sessionEvents=events.filter(event=>(event.sessionId||event.id)===session);if(sessionEvents.some(event=>event.type==='completed'))continue;const reached=sessionEvents.filter(event=>event.type==='step_reached').map(event=>Number(event.step)).filter(Number.isInteger);if(reached.length)counts[Math.max(0,Math.min(guide.steps.length-1,Math.max(...reached)))]++;}return counts;};
const logEvent = async (type, guideId, extra={}) => {
  try { const response = await fetch('/api/events',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type,guideId,sessionId:state.sessionId,...extra})}); if(response.ok){const data=await response.json();db.events.push(data.event);} }
  catch { /* Events are saved by the local app server when it is running. */ }
};
const initials = name => (name||'A').trim().split(/\s+/).slice(0,2).map(part=>part[0]?.toUpperCase()||'').join('');
const categoryNames = ['Компьютеры','Мониторы и периферия','Техника и гаджеты','Кухня и выпечка','Дом и быт','Учёба и навыки'];
const categoryGroups = { 'Компьютеры':['Технологии','Разработка','Компьютеры'], 'Мониторы и периферия':['Мониторы и периферия'], 'Техника и гаджеты':['Технологии','Разработка','Техника и гаджеты'], 'Кухня и выпечка':['Кухня и выпечка'], 'Дом и быт':['Дом и быт','Быт'], 'Учёба и навыки':['Учёба и навыки','Учёба'] };
const categories = () => ['Все',...categoryNames,...new Set(db.guides.map(guide=>guide.category).filter(name=>!categoryNames.includes(name)&&!Object.values(categoryGroups).some(group=>group.includes(name))))];
const categoryMatches = (guide, category) => category==='Все'||(categoryGroups[category]?categoryGroups[category].includes(guide.category):guide.category===category);
const filteredGuides = () => db.guides.filter(guide => guide.published && categoryMatches(guide,state.category) && `${guide.title} ${guide.description} ${guide.category}`.toLowerCase().includes(state.query.toLowerCase()));
const artFiles = { 'build-pc':'build-pc.svg','install-docker':'install-docker.svg','lab-report':'lab-report.svg','uni-certificate':'uni-certificate.svg' };
const artwork = guide => guide.coverImage || `/assets/guides/${artFiles[guide.id]||'generic.svg'}`;
const toast = message => { state.toast=message; render(); setTimeout(()=>{state.toast=null;render();},2600); };

function old_sidebar() {
  const links=[['home','grid','Обзор'],['catalog','book','Каталог'],['author','edit','Мои инструкции'],['analytics','chart','Аналитика']];
  return `<aside class="sidebar"><a class="brand" href="#" data-page="home"><span class="brand-mark">s<span>.</span></span><span class="brand-name">stepwise<span>ПРОСТО ПО ШАГАМ</span></span></a><div class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav class="side-nav">${links.map(([page,ico,label])=>`<button class="nav-link ${state.page===page?'active':''}" data-page="${page}">${icon(ico,18)}<span>${label}</span>${page==='author'?'<span class="nav-count">'+db.guides.filter(g=>g.author===db.author.name).length+'</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="ai-card"><div class="ai-card-icon">${icon('sparkle',17)}</div><div><b>Умные инструкции</b><p>Создавайте и улучшайте знания вместе.</p></div></div><button class="profile-chip" data-action="profile"><span class="avatar">${escapeHtml(initials(db.author.name))}</span><span class="profile-text"><b>${escapeHtml(db.author.name)}</b><small>Автор проекта</small></span><span class="profile-dots">···</span></button></div></aside>`;
}
function old_topbar() { const titles={home:['Рабочее пространство','Добро пожаловать обратно'],catalog:['Библиотека','Найдите нужную инструкцию'],author:['Мои публикации','Управляйте своими инструкциями'],analytics:['Аналитика','Понимайте, что помогает людям завершить задачу'],reader:['Пошаговый режим','Двигайтесь к результату спокойно'],create:['Редактор инструкции','Соберите понятный маршрут к результату']}; const [eyebrow,title]=titles[state.page]||titles.home; return `<header class="topbar"><button class="mobile-brand" data-page="home">${icon('menu')}<b>STEPWISE</b></button><div class="top-title"><span>${eyebrow}</span><b>${title}</b></div><div class="top-actions"><button class="icon-button top-search" data-action="focus-search" aria-label="Поиск">${icon('search',18)}</button><button class="top-create" data-action="create">${icon('plus',17)}<span>Новая инструкция</span></button><button class="avatar top-avatar" data-action="profile" aria-label="Профиль">${escapeHtml(initials(db.author.name))}</button></div></header>`; }
function card(guide,index=0) {
  return `<article class="guide-card ${guide.accent||'violet'}" style="--delay:${index*55}ms"><button class="card-open" data-action="open" data-id="${escapeHtml(guide.id)}" aria-label="Открыть ${escapeHtml(guide.title)}"></button><div class="card-top"><span class="category-tag">${escapeHtml(guide.category)}</span><span class="card-menu">${icon('external',15)}</span></div><div class="guide-art"><img src="${escapeHtml(artwork(guide))}" alt="" loading="lazy"><span class="art-label">${String(guide.steps.length).padStart(2,'0')} ШАГОВ</span></div><h3>${escapeHtml(guide.title)}</h3><p>${escapeHtml(guide.description)}</p><div class="card-footer"><span>${icon('clock',15)} ${guide.duration} мин</span><span class="difficulty">${escapeHtml(guide.difficulty)}</span><span class="card-arrow">${icon('arrow',17)}</span></div></article>`;
}
function old_intro() { return `<section class="hero-panel"><div class="hero-copy"><div class="overline"><span class="pulse-dot"></span> ЗНАНИЯ, КОТОРЫЕ ВЕДУТ К ДЕЙСТВИЮ</div><h1>Сложное становится<br><em>простым по шагам.</em></h1><p>Практические инструкции, которые помогают уверенно пройти путь от «не знаю, с чего начать» до готового результата.</p><div class="hero-actions"><button class="button button-primary" data-page="catalog">Открыть каталог ${icon('arrow',16)}</button><button class="button button-quiet" data-action="create">Создать инструкцию ${icon('plus',16)}</button></div><div class="hero-proof"><div class="proof-avatars"><i>A</i><i>S</i><i>M</i></div><span><b>${db.guides.filter(g=>g.published).length} полезных маршрута</b><small>и каждый начинается с первого шага</small></span></div></div><div class="hero-visual"><div class="visual-grid"></div><div class="visual-ring ring-outer"></div><div class="visual-ring ring-inner"></div><div class="visual-center"><span class="center-sparkle">✳</span></div><div class="visual-note note-one"><span class="note-icon note-violet">${icon('check',15)}</span><span><b>Понятный план</b><small>без лишнего шума</small></span><i>✓</i></div><div class="visual-note note-two"><span class="note-icon note-blue">${icon('chart',15)}</span><span><b>Прогресс</b><small>шаг за шагом</small></span></div><span class="visual-coordinate">54°20' N&nbsp; 48°22' E</span></div><div class="hero-index">01 <span>/</span> 04</div></section>`; }
function old_home() { const guides=filteredGuides().slice(0,3); return `${intro()}<section class="section-block"><div class="section-heading"><div><span class="section-kicker">НАЧНИТЕ СЕЙЧАС</span><h2>Популярные инструкции</h2><p>Выберите задачу — и разберитесь в ней спокойно.</p></div><button class="text-link" data-page="catalog">Вся библиотека ${icon('arrow',16)}</button></div><div class="guide-grid">${guides.map(card).join('')}</div></section><section class="bottom-promo"><div class="promo-mark">${icon('sparkle',19)}</div><div><b>Знаете, как сделать это проще?</b><p>Опишите свой опыт — и помогите кому-то пройти тот же путь.</p></div><button class="button button-dark" data-action="create">Поделиться знанием ${icon('arrow',16)}</button></section><footer class="app-footer"><span>STEPWISE <i>•</i> знания, проверенные практикой</span><span>Сделано, чтобы каждый следующий шаг был понятен.</span></footer>`; }
function old_catalog() { return `<section class="page-intro"><div><span class="section-kicker">ПОИСК НАЧИНАЕТСЯ ЗДЕСЬ</span><h1>Что хотите сделать?</h1><p>Найдите понятный маршрут к своей цели — с проверенными шагами и без лишней теории.</p></div><div class="catalog-mark">${icon('book',29)}</div></section><div class="catalog-tools"><label class="search-box">${icon('search',19)}<input id="search-input" type="search" placeholder="Например, собрать компьютер..." value="${escapeHtml(state.query)}" autocomplete="off"><kbd>↵</kbd></label><div class="category-row">${categories().map(item=>`<button class="filter-pill ${item===state.category?'selected':''}" data-action="category" data-category="${escapeHtml(item)}">${item==='Все'?'<span class="filter-dot"></span>':''}${escapeHtml(item)}</button>`).join('')}</div></div><div class="result-row"><span><b>${filteredGuides().length}</b> инструкции</span><span class="sort-note">Сначала рекомендуемые <span>⌄</span></span></div><div class="guide-grid catalog-grid">${filteredGuides().map(card).join('')||`<div class="empty-state"><span>${icon('search',25)}</span><b>Пока не нашли инструкцию</b><p>Попробуйте изменить запрос или выбрать другую категорию.</p><button class="button button-quiet" data-action="clear-search">Сбросить поиск</button></div>`}</div>`; }
function guideById(id=state.guideId) { return db.guides.find(guide=>guide.id===id); }
function old_reader() {
  const guide=guideById(); if(!guide) return `<div class="empty-state"><b>Инструкция не найдена</b><button class="button button-primary" data-page="catalog">К каталогу</button></div>`;
  const step=guide.steps[state.step]; const pct=Math.round((state.step+(state.checked.has(state.step)?1:0))/guide.steps.length*100);
  return `<div class="reader-shell"><button class="back-link" data-page="catalog">${icon('back',16)} Каталог <span>/</span> ${escapeHtml(guide.category)}</button><div class="reader-head"><div><span class="section-kicker">${escapeHtml(guide.category)} &nbsp;·&nbsp; ${escapeHtml(guide.difficulty.toUpperCase())}</span><h1>${escapeHtml(guide.title)}</h1><p>${escapeHtml(guide.description)}</p></div><div class="reader-photo-wrap"><img class="reader-hero-image" src="${escapeHtml(artwork(guide))}" alt="" />${guide.coverSource?`<a class="reader-credit" href="${escapeHtml(guide.coverSource)}" target="_blank" rel="noopener noreferrer">Фото: ${escapeHtml(guide.coverCredit||'' )}</a>`:``}</div></div><div class="reader-layout"><aside class="step-rail"><div class="rail-heading"><span>ВАШ МАРШРУТ</span><b>${state.step+1}<i> / ${guide.steps.length}</i></b></div><div class="progress-track"><span style="width:${pct}%"></span></div><div class="step-list">${guide.steps.map((item,index)=>`<button class="step-nav ${index===state.step?'current':''} ${state.checked.has(index)?'done':''}" data-action="jump" data-step="${index}"><span class="step-num">${state.checked.has(index)?icon('check',15):String(index+1).padStart(2,'0')}</span><span>${escapeHtml(item.title)}</span>${index===state.step?'<i class="step-active-dot"></i>':''}</button>`).join('')}</div><div class="rail-tip">${icon('clock',16)} <span>Около <b>${guide.duration} минут</b><small>в спокойном темпе</small></span></div></aside><section class="step-card"><div class="step-card-top"><span>ШАГ ${String(state.step+1).padStart(2,'0')}</span><span>${Math.round((state.step+1)/guide.steps.length*100)}% маршрута</span></div><div class="step-card-body"><h2>${escapeHtml(step.title)}</h2><p>${escapeHtml(step.text)}</p>${step.image?`<figure class="step-photo"><img src="${escapeHtml(step.image)}" alt="Иллюстрация к шагу «${escapeHtml(step.title)}»" loading="lazy"></figure>`:''}${step.tip?`<div class="tip-box"><span>${icon('sparkle',17)}</span><p><b>Полезно знать</b><br>${escapeHtml(step.tip)}</p></div>`:''}<button class="mark-done ${state.checked.has(state.step)?'is-done':''}" data-action="toggle-step">${icon('check',17)}${state.checked.has(state.step)?'Шаг выполнен':'Отметить шаг выполненным'}</button></div><div class="step-card-footer"><button class="button button-quiet" data-action="prev" ${state.step===0?'disabled':''}>${icon('back',16)} Назад</button>${state.step===guide.steps.length-1?`<button class="button button-primary" data-action="finish">Завершить инструкцию ${icon('check',16)}</button>`:`<button class="button button-primary" data-action="next">Следующий шаг ${icon('arrow',16)}</button>`}</div></section></div><div class="reader-outcome">${icon('check',16)} <span><b>Результат:</b> ${escapeHtml(guide.outcome||'Инструкция пройдена.')}</span></div></div>`;
}
function authorPage() { const own=db.guides.filter(g=>g.author===db.author.name); return `<section class="page-intro"><div><span class="section-kicker">ВАШ ВКЛАД В БИБЛИОТЕКУ</span><h1>Мои инструкции</h1><p>Создавайте маршруты, которыми хочется делиться, и улучшайте их со временем.</p></div><button class="button button-primary" data-action="create">${icon('plus',17)} Новая инструкция</button></section><div class="stats-grid"><div class="stat-card"><span>Опубликовано</span><b>${own.length.toString().padStart(2,'0')}</b><small>инструкций</small><i class="stat-icon purple">${icon('book',17)}</i></div><div class="stat-card"><span>Начали прохождение</span><b>${own.reduce((n,g)=>n+eventCount('started',g.id),0).toString().padStart(2,'0')}</b><small>реальные запуски</small><i class="stat-icon blue">${icon('arrow',17)}</i></div><div class="stat-card"><span>Завершили</span><b>${own.reduce((n,g)=>n+eventCount('completed',g.id),0).toString().padStart(2,'0')}</b><small>завершённых маршрута</small><i class="stat-icon green">${icon('check',17)}</i></div></div><div class="list-heading"><div><h2>Ваши публикации</h2><p>Нажмите на инструкцию, чтобы посмотреть или отредактировать её.</p></div></div><div class="own-list">${own.map(g=>`<article class="own-row"><button class="own-main" data-action="open" data-id="${escapeHtml(g.id)}"><span class="own-art ${g.accent}"><img src="${escapeHtml(artwork(g))}" alt="" loading="lazy"></span><span class="own-copy"><b>${escapeHtml(g.title)}</b><small>${escapeHtml(g.category)} <i>·</i> ${g.steps.length} шагов <i>·</i> ${g.duration} мин</small></span></button><span class="published-tag"><i></i> Опубликовано</span><span class="own-views">${eventCount('started',g.id)} <small>стартов</small></span><button class="icon-button edit-button" data-action="edit" data-id="${escapeHtml(g.id)}" aria-label="Редактировать">${icon('edit',17)}</button></article>`).join('')||`<div class="empty-state"><span>${icon('plus',24)}</span><b>Здесь появятся ваши инструкции</b><p>Создайте первую — редактор поможет структурировать её по шагам.</p><button class="button button-primary" data-action="create">Создать первую инструкцию ${icon('arrow',16)}</button></div>`}</div>`; }
function analytics() { const own=db.guides.filter(g=>g.author===db.author.name), ownIds=own.map(guide=>guide.id), allStarts=own.reduce((sum,g)=>sum+eventCount('started',g.id),0), allDone=own.reduce((sum,g)=>sum+eventCount('completed',g.id),0), rate=allStarts?Math.round(allDone/allStarts*100):0, weeks=weeklyStarts(ownIds), maxWeek=Math.max(1,...weeks); return `<section class="page-intro analytics-intro"><div><span class="section-kicker">ОПЫТ ПОМОГАЕТ СТАТЬ ЛУЧШЕ</span><h1>Ваши результаты</h1><p>Здесь только действия, которые люди действительно совершили в вашем приложении.</p></div><div class="live-indicator"><span></span> СОБЫТИЯ В РЕАЛЬНОМ ВРЕМЕНИ</div></section><div class="analytics-grid"><article class="analytics-card primary-metric"><div class="metric-label">НАЧАЛИ ПРОХОЖДЕНИЕ <span>${icon('arrow',15)}</span></div><b>${allStarts}</b><p>запусков ваших инструкций</p><div class="mini-bars ${allStarts?'':'empty'}">${weeks.map(value=>`<i title="${value} запусков" style="height:${allStarts?Math.max(7,Math.round(value/maxWeek*100)):4}%"></i>`).join('')}</div><small>Число запусков за последние 12 недель</small></article><article class="analytics-card"><div class="metric-label">ЗАВЕРШИЛИ <span class="metric-icon green">${icon('check',16)}</span></div><b>${allDone}</b><p>завершённых инструкций</p><div class="completion-ring" style="--progress:${rate}%"><div><b>${rate}%</b><small>до результата</small></div></div><small>Доля завершений среди всех запусков</small></article></div><div class="list-heading analytics-list-heading"><div><h2>Где остановились</h2><p>Последний достигнутый шаг в незавершённых прохождениях.</p></div></div><div class="analytics-table">${own.map(guide=>{const starts=eventCount('started',guide.id),done=eventCount('completed',guide.id),counts=stopCounts(guide),max=Math.max(1,...counts);return `<div class="analytic-guide"><div class="analytic-guide-head"><span class="own-art ${guide.accent}">${`<img src="${escapeHtml(artwork(guide))}" alt="" loading="lazy">`}</span><span><b>${escapeHtml(guide.title)}</b><small>${starts} запусков&nbsp; · &nbsp;${done} завершено</small></span><span class="completion-value">${starts?Math.round(done/starts*100):0}%<small>завершили</small></span></div><div class="step-bars">${guide.steps.map((step,i)=>`<div class="step-bar-row"><span>Шаг ${String(i+1).padStart(2,'0')}</span><div class="bar-bg"><i style="width:${starts?Math.max(4,Math.round(counts[i]/max*100)):0}%"></i></div><small>${counts[i]}</small></div>`).join('')}</div></div>`}).join('')||`<div class="empty-state compact-empty"><b>Пока нет данных</b><p>Опубликуйте инструкцию и поделитесь ею. События прохождения появятся здесь автоматически.</p><button class="button button-quiet" data-action="create">Создать инструкцию ${icon('arrow',15)}</button></div>`}</div><p class="data-note">${icon('warning',15)} Пока приложение работает локально на этом компьютере. Когда им начнут пользоваться разные люди через общий сервер, здесь появится общая статистика.</p>`; }
function old_editor() {
  const guide=state.editingId?guideById(state.editingId):null;
  const draft=guide||state.draft||null;
  const steps=draft?.steps?.length?draft.steps:[{title:'',text:'',tip:'',image:''},{title:'',text:'',tip:'',image:''}];
  return `<section class="editor-wrap"><button class="back-link" data-page="author">${icon('back',16)} Мои инструкции</button><div class="editor-head"><div><span class="section-kicker">${guide?'ОБНОВИТЕ СВОЙ МАРШРУТ':'ПОДЕЛИТЕСЬ ОПЫТОМ'}</span><h1>${guide?'Редактировать инструкцию':'Создать инструкцию'}</h1><p>Хорошая инструкция ведёт к конкретному результату — шаг за шагом.</p></div><div class="editor-head-actions">${!guide?`<button class="button button-quiet" type="button" data-action="ai-create">${icon('sparkle',16)} Черновик с ИИ</button>`:''}<span class="editor-ornament">${icon('edit',24)}</span></div></div><form id="guide-form" class="guide-form"><div class="form-section"><div class="form-section-title"><span>01</span><div><b>О чём эта инструкция?</b><small>Помогите читателю понять, куда он попадёт.</small></div></div><div class="field-grid"><label class="field full-field">Название инструкции<input name="title" required maxlength="90" placeholder="Например, собираем компьютер с нуля" value="${escapeHtml(draft?.title||'')}"></label><label class="field full-field">Краткое описание<textarea name="description" required maxlength="240" rows="3" placeholder="Что читатель узнает или сможет сделать после прохождения?">${escapeHtml(draft?.description||'')}</textarea></label><label class="field">Категория<select name="category">${['Технологии','Разработка','Учёба','Быт','Творчество','Другое'].map(x=>`<option ${draft?.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Сложность<select name="difficulty">${['Легко','Средне','Продвинуто'].map(x=>`<option ${draft?.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Время, минут<input name="duration" type="number" min="1" max="999" value="${draft?.duration||30}"></label><label class="field">Что понадобится<input name="materials" placeholder="Инструменты, материалы — через запятую" value="${escapeHtml(draft?.materials?.join(', ')||'')}"></label><label class="field full-field">Результат<textarea name="outcome" rows="2" placeholder="Как поймём, что инструкция пройдена?">${escapeHtml(draft?.outcome||'')}</textarea></label><div class="field full-field image-field"><span>Обложка инструкции <small>Поможет быстрее найти её в каталоге.</small></span><div class="image-control"><div class="image-preview cover-preview" data-preview="cover">${draft?.coverImage?`<img src="${escapeHtml(draft.coverImage)}" alt="Текущая обложка">`:`<span>${icon('book',20)} Фото обложки</span>`}</div><div class="image-actions"><label class="button button-quiet image-pick">${icon('plus',15)} Выбрать фото<input type="file" class="image-input" data-image-kind="cover" accept="image/jpeg,image/png,image/webp"></label><button class="text-link remove-image" type="button" data-action="clear-image" data-image-kind="cover">Убрать фото</button><small>JPG, PNG или WebP, до 5 МБ</small></div></div><input type="hidden" class="image-remove-value" data-image-kind="cover" value="0"></div></div></div><div class="form-section steps-form-section"><div class="form-section-title"><span>02</span><div><b>Разбейте путь на шаги</b><small>Добавьте фото там, где оно поможет выполнить действие правильно.</small></div></div><div id="steps-editor" class="steps-editor">${steps.map((step,i)=>stepField(step,i)).join('')}</div><button type="button" class="add-step" data-action="add-step">${icon('plus',16)} Добавить шаг</button></div><div class="editor-footer"><span>${icon('check',16)} Можно отредактировать после публикации</span><div><button class="button button-quiet" type="button" data-page="author">Отмена</button><button class="button button-primary" type="submit">${guide?'Сохранить изменения':'Опубликовать инструкцию'} ${icon('arrow',16)}</button></div></div></form></section>`;
}
function old_stepField(step,index) { return `<div class="step-editor-card"><div class="step-editor-heading"><span class="step-editor-num">${String(index+1).padStart(2,'0')}</span><b>Шаг ${index+1}</b><button type="button" class="remove-step" data-action="remove-step" aria-label="Удалить шаг">${icon('close',16)}</button></div><label class="field">Название шага<input class="step-title-input" required maxlength="90" placeholder="Например, подготовьте рабочее место" value="${escapeHtml(step.title)}"></label><label class="field">Что нужно сделать?<textarea class="step-text-input" required maxlength="900" rows="3" placeholder="Опишите действия простыми и точными фразами">${escapeHtml(step.text)}</textarea></label><label class="field tip-field">Полезный совет <span>необязательно</span><input class="step-tip-input" maxlength="240" placeholder="Подсказка или важное предупреждение" value="${escapeHtml(step.tip||'')}"></label><div class="field image-field step-image-field"><span>Фото для этого шага <small>Необязательно</small></span><div class="image-control"><div class="image-preview step-image-preview" data-preview="step">${step.image?`<img src="${escapeHtml(step.image)}" alt="Фото шага">`:`<span>${icon('book',17)} Фото шага</span>`}</div><div class="image-actions"><label class="button button-quiet image-pick">${icon('plus',15)} Выбрать фото<input type="file" class="image-input" data-image-kind="step" accept="image/jpeg,image/png,image/webp"></label><button class="text-link remove-image" type="button" data-action="clear-image" data-image-kind="step">Убрать фото</button><small>JPG, PNG или WebP, до 5 МБ</small></div></div><input type="hidden" class="image-remove-value" data-image-kind="step" value="0"></div></div>`; }
function aiModal() { return `<div class="modal-backdrop" data-action="close-modal"><section class="profile-modal ai-modal" role="dialog" aria-modal="true" aria-labelledby="ai-title"><button class="modal-close" data-action="close-modal" aria-label="Закрыть">${icon('close',18)}</button><div class="modal-avatar ai-modal-avatar">${icon('sparkle',20)}</div><span class="section-kicker">ПОМОЩЬ В СОЗДАНИИ</span><h2 id="ai-title">О чём будет инструкция?</h2><p>Опиши задачу или вставь свои заметки. ИИ соберёт черновик, который ты сможешь проверить и отредактировать.</p>${state.busy?`<div class="ai-loading ai-loading-top" role="status" aria-live="polite"><span class="ai-spinner"></span><span><b>Готовим черновик</b><small>Собираем шаги. Это может занять до минуты.</small></span></div>`:''}<form id="ai-form" class="ai-form ${state.busy?'is-loading':''}"><label class="field">Тема или исходный текст<textarea name="topic" required maxlength="6000" rows="6" ${state.busy?'disabled':''} placeholder="Например: как подготовить компьютер к установке Windows. Укажи, для какой системы инструкция.">${escapeHtml(state.aiTopic)}</textarea></label>${state.aiError?`<p class="ai-error" role="alert">${escapeHtml(state.aiError)}</p>`:''}${state.busy?`<div class="ai-loading" role="status" aria-live="polite"><span class="ai-spinner"></span><span><b>Готовим черновик</b><small>Собираем шаги и проверяем структуру. Это может занять до минуты.</small></span></div>`:''}<button class="button button-primary ai-submit" type="submit" ${state.busy?'disabled':''}>${state.busy?'Запрос отправлен…':'Создать черновик'} ${state.busy?'<span class="ai-button-spinner"></span>':icon('sparkle',16)}</button></form><small class="local-note">Черновик появится здесь автоматически. Ты проверишь его и только потом опубликуешь.</small></section></div>`; }
function old_profileModal() { return `<div class="modal-backdrop" data-action="close-modal"><section class="profile-modal" role="dialog" aria-modal="true" aria-labelledby="profile-title"><button class="modal-close" data-action="close-modal">${icon('close',18)}</button><div class="modal-avatar">${escapeHtml(initials(db.author.name))}</div><span class="section-kicker">ВАШ ПРОФИЛЬ АВТОРА</span><h2 id="profile-title">Как вас показывать?</h2><p>Имя появится рядом с созданными вами инструкциями.</p><form id="profile-form"><label class="field">Имя автора<input name="name" required maxlength="50" value="${escapeHtml(db.author.name)}"></label><label class="field">Электронная почта <span>необязательно</span><input name="email" type="email" placeholder="you@example.com" value="${escapeHtml(db.author.email||'')}"></label><button class="button button-primary" type="submit">Сохранить профиль ${icon('arrow',16)}</button></form><small class="local-note">Профиль пока хранится на этом компьютере.</small></section></div>`; }
function old_render() { const views={home,catalog,reader,author:authorPage,analytics,create:editor}; const content=(views[state.page]||home)(); app.innerHTML=`<div class="app-shell">${sidebar()}<main class="main-area">${topbar()}<div class="page-content ${state.page==='home'?'home-content':''} ${state.page==='reader'?'reader-page':''}">${content}</div></main></div>${state.modal==='profile'?profileModal():state.modal==='ai'?aiModal():''}${state.toast?`<div class="toast">${icon('check',16)} ${escapeHtml(state.toast)}</div>`:''}`; updateRemoveButtons(); }

function readSavedProgress(){try{return JSON.parse(localStorage.getItem('stepwise-progress')||'{}')}catch{return {}}}
function saveGuideProgress(){const all=readSavedProgress();if(state.guideId&&!state.completed){all[state.guideId]={step:state.step,checked:[...state.checked],sessionId:state.sessionId,updatedAt:Date.now()};localStorage.setItem('stepwise-progress',JSON.stringify(all))}}
function intro(){return `<section class="hero-panel blue-hero"><div class="hero-copy"><div class="overline"><span class="pulse-dot"></span> ПОНЯТНЫЕ ИНСТРУКЦИИ ДЛЯ ЖИЗНИ</div><h1>Сложное становится<br><em>понятным по шагам.</em></h1><p>Сначала выбери, что хочешь сделать. Мы поможем найти последовательность действий и спокойно дойти до результата.</p><div class="hero-actions"><button class="button button-primary" data-scroll="categories">Выбрать тему ${icon('arrow',16)}</button><button class="button button-quiet" data-action="create">Поделиться опытом ${icon('plus',16)}</button></div><div class="hero-proof"><span class="proof-mark">S<span>↗</span></span><span><b>STEPWISE</b><small>простые шаги к полезным результатам</small></span></div></div><div class="hero-visual cube-visual"><div class="visual-halo"></div><div class="visual-orbit orbit-a"></div><div class="visual-orbit orbit-b"></div><div class="hero-cube-wrap" id="hero-cube" tabindex="0" role="application" aria-label="Интерактивный куб. Перетаскивайте мышью или вращайте стрелками." aria-describedby="cube-hint"><div class="hero-cube"><i class="cube-face front"></i><i class="cube-face back"></i><i class="cube-face right"></i><i class="cube-face left"></i><i class="cube-face top"></i><i class="cube-face bottom"></i><i class="cube-light"></i></div></div><div class="cube-caption"><span id="cube-hint">ПЕРЕТАЩИ КУБИК</span><button type="button" data-action="reset-cube">↻ Сбросить</button></div><div class="cube-badge"><small>ОДИН ШАГ</small><b>ЗА РАЗ</b><span>01 / ∞</span></div></div></section>`}
function sidebar(){const links=[['home','grid','Главная'],['catalog','book','Каталог'],['author','edit','Мои инструкции'],['analytics','chart','Аналитика']];return `<aside class="sidebar"><a class="brand" href="#" data-page="home"><span class="brand-mark">S<span>↗</span></span><span class="brand-name">STEPWISE<span>ПРОСТО ПО ШАГАМ</span></span></a><div class="nav-label">НАВИГАЦИЯ</div><nav class="side-nav">${links.map(([page,ico,label])=>`<button class="nav-link ${state.page===page?'active':''}" data-page="${page}" aria-current="${state.page===page?'page':'false'}">${icon(ico,18)}<span>${label}</span>${page==='author'?`<span class="nav-count">${db.guides.filter(g=>g.author===db.author.name).length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="ai-card"><div class="ai-card-icon">${icon('sparkle',17)}</div><div><b>Есть опыт?</b><p>Собери его в инструкцию.</p></div><button data-action="create" aria-label="Создать инструкцию">${icon('plus',16)}</button></div><button class="profile-chip" data-action="profile"><span class="avatar">${escapeHtml(initials(db.author.name))}</span><span class="profile-text"><b>${escapeHtml(db.author.name)}</b><small>Профиль и статистика</small></span><span class="profile-dots">↗</span></button></div></aside>`}
function topbar(){const titles={home:['STEPWISE','Выберите направление'],catalog:['Каталог','Найдите нужную инструкцию'],author:['Ваши публикации','Создавайте и улучшайте маршруты'],analytics:['Аналитика','Результаты ваших инструкций'],reader:['Пошаговый режим','Продолжайте в своём темпе'],create:['Редактор','Соберите понятную инструкцию']};const[eyebrow,title]=titles[state.page]||titles.home;return `<header class="topbar"><button class="mobile-brand" data-page="home"><span class="brand-mark">S</span><b>STEPWISE</b></button><div class="top-title"><span>${eyebrow}</span><b>${title}</b></div><div class="top-actions"><button class="icon-button top-search" data-action="focus-search" aria-label="Перейти к поиску">${icon('search',18)}<span class="search-word">Найти</span></button><button class="top-create" data-action="create">${icon('plus',17)}<span>Новая инструкция</span></button><button class="avatar top-avatar" data-action="profile" aria-label="Профиль ${escapeHtml(db.author.name)}">${escapeHtml(initials(db.author.name))}</button></div></header>`}
function home(){const progress=readSavedProgress();const resume=Object.entries(progress).map(([id,p])=>({guide:db.guides.find(g=>g.id===id),...p})).filter(x=>x.guide).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0))[0];const cats=[['Компьютеры','ПК, Windows и программы','⌘','https://images.unsplash.com/photo-1741392077898-2a4cce1f54b9?auto=format&fit=crop&w=900&q=85','#48a0ff'],['Мониторы и периферия','Подключение и настройки','▣','https://images.unsplash.com/photo-1557338016-706b8768a3e5?auto=format&fit=crop&w=900&q=85','#b6ff45'],['Техника и гаджеты','Устройства и полезные функции','◈','https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=900&q=85','#ff59dc'],['Кухня и выпечка','Рецепты и кухонные приборы','✳','https://images.unsplash.com/photo-1635321593217-40050ad13c74?auto=format&fit=crop&w=900&q=85','#ffb84d'],['Дом и быт','Практичные повседневные задачи','⌂','https://images.unsplash.com/photo-1774853107769-c80031c15220?auto=format&fit=crop&w=900&q=85','#55e1c0'],['Учёба и навыки','Понятные способы учиться','＋','https://images.unsplash.com/photo-1510519138101-570d1dca3d66?auto=format&fit=crop&w=900&q=85','#a98bff']];return `${intro()}${resume?`<section class="resume-panel"><div><span class="section-kicker">ПРОДОЛЖИТЬ С МЕСТА ОСТАНОВКИ</span><h2>${escapeHtml(resume.guide.title)}</h2><p>Шаг ${Math.min(resume.step+1,resume.guide.steps.length)} из ${resume.guide.steps.length} · ${escapeHtml(resume.guide.category)}</p></div><button class="button button-primary" data-action="resume" data-id="${escapeHtml(resume.guide.id)}">Продолжить ${icon('arrow',16)}</button></section>`:''}<section class="section-block category-home" id="categories"><div class="section-heading"><div><span class="section-kicker">НАЧНИ С ТОГО, ЧТО ТЕБЕ НУЖНО</span><h2>Какую задачу решаем?</h2><p>Выбери направление — конкретные инструкции появятся следующим шагом.</p></div><button class="text-link" data-page="catalog">Открыть весь каталог ${icon('arrow',16)}</button></div><div class="home-category-grid">${cats.map(([name,desc,symbol,image,accent],i)=>`<button class="home-category" style="--tile-accent:${accent}" data-action="browse-category" data-category="${escapeHtml(name)}"><img class="home-category-photo" src="${image}" alt="" loading="lazy" referrerpolicy="no-referrer"><span class="home-category-index">0${i+1}</span><span class="home-category-symbol">${symbol}</span><b>${escapeHtml(name)}</b><small>${escapeHtml(desc)}</small><i>${icon('arrow',17)}</i></button>`).join('')}</div></section><section class="home-how section-block" id="how"><div class="section-heading"><div><span class="section-kicker">ПРОСТОЙ ПРИНЦИП</span><h2>От вопроса — к результату.</h2></div><p>STEPWISE помогает разобраться по пути, а не перегружает длинной инструкцией.</p></div><div class="home-how-grid"><article><span>01</span><b>Выбери тему</b><p>Категории помогают найти нужную область без догадок о том, что тебе интересно.</p></article><article><span>02</span><b>Открой маршрут</b><p>Посмотри на шаги, подготовь необходимое и оцени время.</p></article><article><span>03</span><b>Действуй спокойно</b><p>Выполняй по одному шагу, отмечай прогресс и возвращайся позже.</p></article></div></section><section class="bottom-promo"><div class="promo-mark">${icon('sparkle',19)}</div><div><b>Знаешь, как сделать это проще?</b><p>Собери свой опыт в понятную инструкцию для других.</p></div><button class="button button-dark" data-action="create">Создать инструкцию ${icon('arrow',16)}</button></section><footer class="app-footer"><span>STEPWISE <i>•</i> просто по шагам</span><a href="mailto:hello@stepwise.example">Обратная связь</a></footer>`}
function catalog(){const shown=filteredGuides();return `<section class="page-intro"><div><span class="section-kicker">БИБЛИОТЕКА МАРШРУТОВ</span><h1>Что хотите сделать?</h1><p>Сначала выберите направление или сразу найдите задачу по названию.</p></div><div class="catalog-mark">${icon('book',29)}</div></section><div class="catalog-tools"><label class="search-box">${icon('search',19)}<input id="search-input" type="search" placeholder="Например, подключить монитор…" value="${escapeHtml(state.query)}" autocomplete="off"><kbd>НАЙТИ</kbd></label><div class="category-row">${categories().map(item=>`<button class="filter-pill ${item===state.category?'selected':''}" data-action="category" data-category="${escapeHtml(item)}">${item==='Все'?'<span class="filter-dot"></span>':''}${escapeHtml(item)}</button>`).join('')}</div></div><div class="result-row"><span><b>${shown.length}</b> ${shown.length===1?'инструкция':shown.length>1?'инструкции':'инструкций'}</span><button class="sort-note" data-action="clear-search">${state.query||state.category!=='Все'?'Сбросить фильтры ×':''}</button></div><div class="guide-grid catalog-grid">${shown.map(card).join('')||`<div class="empty-state"><span>${icon('search',25)}</span><b>${db.guides.length?'Пока не нашли инструкцию':'В каталоге пока пусто'}</b><p>${db.guides.length?'Измени запрос или категорию — или предложи свой маршрут.':'Создай первую инструкцию, чтобы наполнить библиотеку.'}</p>${db.guides.length?'<button class="button button-quiet" data-action="clear-search">Сбросить фильтры</button>':'<button class="button button-primary" data-action="create">Создать первую инструкцию</button>'}</div>`}</div>`}
function profileModal(){const own=db.guides.filter(g=>g.author===db.author.name),starts=own.reduce((n,g)=>n+eventCount('started',g.id),0),done=own.reduce((n,g)=>n+eventCount('completed',g.id),0),rate=starts?Math.round(done/starts*100):0;return `<div class="modal-backdrop" data-action="close-modal"><section class="profile-modal profile-modal-wide" role="dialog" aria-modal="true" aria-labelledby="profile-title"><button class="modal-close" data-action="close-modal" aria-label="Закрыть">${icon('close',18)}</button><div class="profile-overview"><div class="modal-avatar">${escapeHtml(initials(db.author.name))}</div><div><span class="section-kicker">ВАШ ПРОФИЛЬ И РЕЗУЛЬТАТЫ</span><h2 id="profile-title">${escapeHtml(db.author.name)}</h2><p>${escapeHtml(db.author.email||'Автор STEPWISE')}</p></div></div><div class="profile-stats"><article><small>МОИ ИНСТРУКЦИИ</small><b>${own.length}</b></article><article><small>СТАРТОВ</small><b>${starts}</b></article><article><small>ЗАВЕРШЕНО</small><b>${done}</b></article><article><small>ДОЛЯ ЗАВЕРШЕНИЙ</small><b>${rate}%</b></article></div><form id="profile-form" class="profile-form-inline"><label class="field">Имя автора<input name="name" required maxlength="50" value="${escapeHtml(db.author.name)}"></label><label class="field">Электронная почта <span>необязательно</span><input name="email" type="email" placeholder="you@example.com" value="${escapeHtml(db.author.email||'')}"></label><button class="button button-primary" type="submit">Сохранить профиль ${icon('arrow',16)}</button></form><div class="profile-recent"><div><b>Мои публикации</b><span>${own.length?`${own.length} инструкций`:'Пока пусто'}</span></div>${own.slice(0,4).map(g=>`<div class="profile-guide"><span>${escapeHtml(g.title)}</span><small>${eventCount('started',g.id)} стартов · ${eventCount('completed',g.id)} завершено</small></div>`).join('')||'<p>Опубликуйте инструкцию — здесь появятся её просмотры и завершения.</p>'}<button class="button button-quiet" data-page="author">Открыть мои инструкции ${icon('arrow',15)}</button></div></section></div>`}
function cubeControl(){const cube=$('#hero-cube');if(!cube||cube.dataset.ready)return;cube.dataset.ready='1';let x=-12,y=26,drag=false,lx=0,ly=0;const paint=()=>cube.style.transform=`rotateX(${x}deg) rotateY(${y}deg)`;paint();cube.addEventListener('pointerdown',e=>{drag=true;lx=e.clientX;ly=e.clientY;cube.classList.add('dragging');cube.setPointerCapture(e.pointerId);e.preventDefault()});cube.addEventListener('pointermove',e=>{if(!drag)return;y+=(e.clientX-lx)*.7;x=Math.max(-75,Math.min(75,x-(e.clientY-ly)*.7));lx=e.clientX;ly=e.clientY;paint()});const end=()=>{drag=false;cube.classList.remove('dragging')};cube.addEventListener('pointerup',end);cube.addEventListener('pointercancel',end);cube.addEventListener('keydown',e=>{const d=12;if(e.key==='ArrowLeft')y-=d;else if(e.key==='ArrowRight')y+=d;else if(e.key==='ArrowUp')x=Math.max(-75,x-d);else if(e.key==='ArrowDown')x=Math.min(75,x+d);else if(e.key==='Home'){x=-12;y=26}else return;e.preventDefault();paint()});$('[data-action="reset-cube"]')?.addEventListener('click',()=>{x=-12;y=26;paint()})}

function reader(){const g=guideById();if(!g)return `<div class="empty-state"><b>Инструкция не найдена</b><button class="button button-primary" data-page="catalog">В каталог</button></div>`;if(state.completed)return `<section class="completion-screen"><span class="completion-icon">${icon('check',30)}</span><span class="section-kicker">МАРШРУТ ЗАВЕРШЁН</span><h1>Отличная работа.</h1><p>${escapeHtml(g.outcome||'Ты прошёл инструкцию до конца.')}</p><button class="button button-primary" data-page="catalog">Выбрать следующую тему ${icon('arrow',16)}</button></section>`;const s=g.steps[state.step],pct=Math.round(Math.max(state.checked.size,state.step+(state.checked.has(state.step)?1:0))/g.steps.length*100);return `<div class="reader-shell"><button class="back-link" data-page="catalog">${icon('back',16)} Каталог · ${escapeHtml(g.category)}</button><div class="reader-head"><div><span class="section-kicker">${escapeHtml(g.category)} · ${escapeHtml(g.difficulty)} · ${g.duration} МИН</span><h1>${escapeHtml(g.title)}</h1><p>${escapeHtml(g.description)}</p></div>${g.coverImage?`<img class="reader-hero-image" src="${escapeHtml(artwork(g))}" alt="Обложка инструкции">`:''}</div><div class="reader-layout"><aside class="step-rail"><div class="rail-heading"><span>ТВОЙ МАРШРУТ</span><b>${state.step+1}<i> / ${g.steps.length}</i></b></div><div class="progress-track"><span style="width:${pct}%"></span></div><small class="progress-label">${pct}% маршрута</small><div class="step-list">${g.steps.map((x,i)=>`<button class="step-nav ${i===state.step?'current':''} ${state.checked.has(i)?'done':''}" data-action="jump" data-step="${i}" aria-current="${i===state.step?'step':'false'}"><span class="step-num">${state.checked.has(i)?icon('check',15):String(i+1).padStart(2,'0')}</span><span>${escapeHtml(x.title)}</span></button>`).join('')}</div><div class="rail-tip">${icon('clock',16)} Около ${g.duration} минут</div></aside><section class="step-card"><div class="step-card-top"><span>ШАГ ${String(state.step+1).padStart(2,'0')} / ${g.steps.length}</span><span>${state.checked.size} отмечено</span></div><div class="step-card-body"><h2>${escapeHtml(s.title)}</h2><p>${escapeHtml(s.text)}</p>${s.image?`<figure class="step-photo"><img src="${escapeHtml(s.image)}" alt="Фото к шагу ${escapeHtml(s.title)}"></figure>`:''}${s.tip?`<div class="tip-box"><b>Полезно знать</b><p>${escapeHtml(s.tip)}</p></div>`:''}<button class="mark-done ${state.checked.has(state.step)?'is-done':''}" data-action="toggle-step">${icon('check',17)}${state.checked.has(state.step)?'Отмечено':'Отметить шаг выполненным'}</button></div><div class="step-card-footer"><button class="button button-quiet" data-action="prev" ${state.step===0?'disabled':''}>${icon('back',16)} Назад</button><button class="button button-primary" data-action="${state.step===g.steps.length-1?'finish':'next'}">${state.step===g.steps.length-1?'Завершить маршрут':'Следующий шаг'} ${icon('arrow',16)}</button></div></section></div></div>`}
function editor(){const g=state.editingId?guideById(state.editingId):null,d=g||state.draft||{},steps=d.steps?.length?d.steps:[{title:'',text:'',tip:'',image:''},{title:'',text:'',tip:'',image:''}],opts=[...new Set([...(d.category?[d.category]:[]),...categoryNames])];return `<section class="editor-wrap"><button class="back-link" data-page="author">${icon('back',16)} Мои инструкции</button><div class="editor-head"><div><span class="section-kicker">${g?'РЕДАКТИРОВАНИЕ':'НОВЫЙ МАРШРУТ'}</span><h1>${g?'Улучши инструкцию':'Поделись опытом'}</h1><p>Объясни результат и опиши действия так, как объяснил бы другу.</p></div>${!g?`<button class="button button-quiet" type="button" data-action="ai-create">${icon('sparkle',16)} Черновик с ИИ</button>`:''}</div><nav class="editor-jump"><a href="#editor-details">01 · Описание</a><a href="#editor-steps">02 · Шаги (${steps.length})</a><span>2–40 шагов</span></nav><form id="guide-form" class="guide-form"><section class="form-section" id="editor-details"><div class="form-section-title"><span>01</span><div><b>Опиши маршрут</b><small>Название, тема и нужные материалы.</small></div></div><div class="field-grid"><label class="field full-field">Название<input name="title" required maxlength="90" placeholder="Например, подключить второй монитор" value="${escapeHtml(d.title||'')}"></label><label class="field full-field">Что получится в итоге?<textarea name="description" required maxlength="240" rows="2" placeholder="Коротко объясни, чему научится читатель.">${escapeHtml(d.description||'')}</textarea></label><label class="field">Категория<select name="category" required>${opts.map(x=>`<option ${d.category===x?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select></label><label class="field">Сложность<select name="difficulty">${['Легко','Средне','Продвинуто'].map(x=>`<option ${d.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Время, минут<input name="duration" type="number" min="1" max="999" value="${d.duration||30}"></label><label class="field">Что понадобится<input name="materials" placeholder="Через запятую, если нужно" value="${escapeHtml(d.materials?.join(', ')||'')}"></label><label class="field full-field">Результат<textarea name="outcome" rows="2" placeholder="Как понять, что задача выполнена?">${escapeHtml(d.outcome||'')}</textarea></label><div class="field full-field image-field"><span>Обложка <small>Необязательно · JPG, PNG или WebP до 5 МБ</small></span><div class="image-control"><div class="image-preview cover-preview">${d.coverImage?`<img src="${escapeHtml(d.coverImage)}" alt="Обложка инструкции">`:`<span>${icon('book',20)} Добавьте фото</span>`}</div><div class="image-actions"><label class="button button-quiet image-pick">${icon('plus',15)} Выбрать фото<input type="file" class="image-input" data-image-kind="cover" accept="image/jpeg,image/png,image/webp"></label><button class="text-link remove-image" type="button" data-action="clear-image" data-image-kind="cover">Убрать фото</button><input type="hidden" class="image-remove-value" data-image-kind="cover" value="0"></div></div></div></div></section><section class="form-section steps-form-section" id="editor-steps"><div class="form-section-title"><span>02</span><div><b>Разложи на шаги</b><small>Одно понятное действие в каждом. Фото и совет — по желанию.</small></div></div><div id="steps-editor" class="steps-editor">${steps.map(stepField).join('')}</div><button type="button" class="add-step" data-action="add-step">${icon('plus',16)} Добавить шаг</button></section><div class="editor-footer"><span>${icon('check',16)} Можно изменить после публикации</span><div><button class="button button-quiet" type="button" data-page="author">Отмена</button><button class="button button-primary" type="submit">${g?'Сохранить изменения':'Опубликовать инструкцию'} ${icon('arrow',16)}</button></div></div></form></section>`}
function stepField(step,index){return `<article class="step-editor-card" data-image="${escapeHtml(step.image||'')}"><div class="step-editor-heading"><span class="step-editor-num">${String(index+1).padStart(2,'0')}</span><b>Шаг ${index+1}</b><div class="step-controls"><button type="button" data-action="move-step-up" aria-label="Переместить выше">↑</button><button type="button" data-action="move-step-down" aria-label="Переместить ниже">↓</button><button type="button" class="remove-step" data-action="remove-step" aria-label="Удалить шаг">${icon('close',16)}</button></div></div><label class="field">Что сделать? <input class="step-title-input" required maxlength="90" placeholder="Например, выберите нужный разъём" value="${escapeHtml(step.title)}"></label><label class="field">Как это сделать? <textarea class="step-text-input" required maxlength="900" rows="3" placeholder="Опиши действие коротко и по порядку.">${escapeHtml(step.text)}</textarea></label><label class="field tip-field">Подсказка <span>необязательно</span><input class="step-tip-input" maxlength="240" placeholder="Чего не забыть или чего избегать" value="${escapeHtml(step.tip||'')}"></label><div class="field image-field step-image-field"><span>Фото к шагу <small>Необязательно · до 5 МБ</small></span><div class="image-control"><div class="image-preview step-image-preview">${step.image?`<img src="${escapeHtml(step.image)}" alt="Фото шага">`:`<span>${icon('book',17)} Добавить фото</span>`}</div><div class="image-actions"><label class="button button-quiet image-pick">${icon('plus',15)} Выбрать фото<input type="file" class="image-input" data-image-kind="step" accept="image/jpeg,image/png,image/webp"></label><button class="text-link remove-image" type="button" data-action="clear-image" data-image-kind="step">Убрать фото</button><input type="hidden" class="image-remove-value" data-image-kind="step" value="0"></div></div></div></article>`}
function render(){const views={home,catalog,reader,author:authorPage,analytics,create:editor},content=(views[state.page]||home)();app.innerHTML=`<div class="app-shell">${sidebar()}<main class="main-area">${topbar()}<div class="page-content ${state.page==='home'?'home-content':''} ${state.page==='reader'?'reader-page':''}">${content}</div></main></div>${state.modal==='profile'?profileModal():state.modal==='ai'?aiModal():''}${state.toast?`<div class="toast">${icon('check',16)} ${escapeHtml(state.toast)}</div>`:''}`;updateRemoveButtons();cubeControl()}
app.addEventListener('click', async event => {
  const button=event.target.closest('[data-page],[data-action],[data-scroll]'); if(!button)return;
  const page=button.dataset.page, action=button.dataset.action;
  if(button.dataset.scroll){document.getElementById(button.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
  if(page){state.page=page;state.modal=false;render();return;}
  if(action==='create'){state.page='create';state.editingId=null;state.draft=null;render();return;}
  if(action==='profile'){state.modal='profile';render();return;}
  if(action==='ai-create'){state.modal='ai';render();return;}
  if(action==='clear-image'){const card=button.closest('.step-editor-card');const kind=button.dataset.imageKind;const input=kind==='cover'?$('.image-input[data-image-kind="cover"]'):$('.image-input[data-image-kind="step"]',card);const preview=kind==='cover'?$('.cover-preview'):$('.step-image-preview',card);const removed=kind==='cover'?$('.image-remove-value[data-image-kind="cover"]'):$('.image-remove-value[data-image-kind="step"]',card);if(input)input.value='';if(removed)removed.value='1';if(card&&kind==='step')card.dataset.image='';if(preview)preview.innerHTML=`<span>${icon('book',17)} Фото пока нет</span>`;return;}
  if(action==='close-modal'){if(event.target===button||button.classList.contains('modal-close')){state.modal=false;render();}return;}
  if(action==='focus-search'){state.page='catalog';render();$('#search-input')?.focus();return;}
  if(action==='clear-search'){state.query='';state.category='Все';render();return;}
  if(action==='category'){state.category=button.dataset.category;render();return;}
  if(action==='browse-category'){state.category=button.dataset.category;state.query='';state.page='catalog';render();return;}
  if(action==='resume'||action==='open'){state.guideId=button.dataset.id;const saved=readSavedProgress()[state.guideId];state.sessionId=saved?.sessionId||crypto.randomUUID();state.step=saved?.step||0;state.checked=new Set(saved?.checked||[]);state.completed=false;state.page='reader';if(!saved){await logEvent('started',state.guideId);await logEvent('step_reached',state.guideId,{step:0});}render();return;}
  if(action==='edit'){state.editingId=button.dataset.id;state.page='create';render();return;}
  if(action==='add-step'){const host=$('#steps-editor');host.insertAdjacentHTML('beforeend',stepField({title:'',text:'',tip:''},host.children.length));updateRemoveButtons();return;}
  if(action==='remove-step'){const host=$('#steps-editor');if(host.children.length>2){button.closest('.step-editor-card').remove();renumberSteps();updateRemoveButtons();}return;}
  if(action==='move-step-up'||action==='move-step-down'){const host=$('#steps-editor'),item=button.closest('.step-editor-card'),before=item?.previousElementSibling,after=item?.nextElementSibling;if(action==='move-step-up'&&before)host.insertBefore(item,before);if(action==='move-step-down'&&after)host.insertBefore(after,item);renumberSteps();return;}
  if(action==='toggle-step'){if(state.checked.has(state.step))state.checked.delete(state.step);else state.checked.add(state.step);if(state.checked.has(state.step))await logEvent('step_completed',state.guideId,{step:state.step});saveGuideProgress();render();return;}
  if(action==='next'){state.step=Math.min(state.step+1,guideById().steps.length-1);await logEvent('step_reached',state.guideId,{step:state.step});saveGuideProgress();render();return;}
  if(action==='prev'){state.step=Math.max(0,state.step-1);saveGuideProgress();render();return;}
  if(action==='jump'){state.step=Number(button.dataset.step);if(state.step>0)await logEvent('step_reached',state.guideId,{step:state.step});saveGuideProgress();render();return;}
  if(action==='finish'){await logEvent('completed',state.guideId,{step:state.step});state.checked.add(state.step);state.completed=true;const saved=readSavedProgress();delete saved[state.guideId];localStorage.setItem('stepwise-progress',JSON.stringify(saved));state.page='reader';toast('Маршрут завершён — отличная работа!');return;}
});
app.addEventListener('input',event=>{if(event.target.id==='search-input'){const pos=event.target.selectionStart;state.query=event.target.value;render();const next=$('#search-input');next?.focus();next?.setSelectionRange(pos,pos);}if(event.target.name==='topic'&&event.target.closest('#ai-form')){state.aiTopic=event.target.value;state.aiError='';}});
app.addEventListener('change',event=>{
  const input=event.target.closest('.image-input'); if(!input)return;
  const file=input.files?.[0]; if(!file)return;
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Выбери файл JPG, PNG или WebP.');input.value='';return;}
  if(file.size>5_000_000){toast('Фото должно быть меньше 5 МБ.');input.value='';return;}
  const card=input.closest('.step-editor-card'); const preview=input.dataset.imageKind==='cover'?$('.cover-preview'):$('.step-image-preview',card);
  const removed=input.dataset.imageKind==='cover'?$('.image-remove-value[data-image-kind="cover"]'):$('.image-remove-value[data-image-kind="step"]',card);
  if(removed)removed.value='0'; if(preview)preview.innerHTML=`<img src="${URL.createObjectURL(file)}" alt="Предпросмотр фото">`;
});
async function uploadImage(file){
  if(!file)return '';
  if(file.size>5_000_000)throw new Error('Фото должно быть меньше 5 МБ.');
  const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Не удалось прочитать фото.'));reader.readAsDataURL(file);});
  const response=await fetch('/api/uploads',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type:file.type,data})});
  const result=await response.json(); if(!response.ok)throw new Error(result.error||'Не удалось загрузить фото.'); return result.url;
}
app.addEventListener('submit',async event=>{
  if(event.target.id==='ai-form'){
    event.preventDefault();if(state.busy)return;state.aiTopic=String(new FormData(event.target).get('topic')||'').trim();if(!state.aiTopic){event.target.elements.topic.focus();return;}state.aiError='';state.busy=true;render();
    try{const response=await fetch('/api/ai/draft',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic:state.aiTopic})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Не удалось создать черновик.');state.draft=result.draft;state.editingId=null;state.modal=false;state.page='create';state.busy=false;state.aiTopic='';render();toast('Черновик готов — проверь шаги перед публикацией.');}
    catch(error){state.busy=false;state.aiError=error.message||'Не удалось создать черновик. Проверь соединение и попробуй ещё раз.';render();}
    return;
  }
  if(event.target.id==='profile-form'){
    event.preventDefault();const form=new FormData(event.target);const author={name:String(form.get('name')).trim(),email:String(form.get('email')||'').trim()};
    try{const response=await fetch('/api/profile',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(author)});const result=await response.json();if(!response.ok){toast(result.error||'Не удалось сохранить профиль.');return;}db.author=result.author;state.modal=false;render();toast('Профиль обновлён');}catch{toast('Сервер недоступен. Профиль не изменён.');}return;
  }
  if(event.target.id==='guide-form'){
    event.preventDefault();if(state.busy)return;state.busy=true;
    try{
      const form=new FormData(event.target), stepCards=[...$('#steps-editor').children], existing=state.editingId?guideById(state.editingId):null;
      const coverInput=$('.image-input[data-image-kind="cover"]'), coverRemoved=$('.image-remove-value[data-image-kind="cover"]')?.value==='1';
      let coverImage=coverRemoved?'':(existing?.coverImage||state.draft?.coverImage||''); if(coverInput.files?.[0])coverImage=await uploadImage(coverInput.files[0]);
      const steps=await Promise.all(stepCards.map(async(card,index)=>{
        const input=$('.image-input[data-image-kind="step"]',card), removed=$('.image-remove-value[data-image-kind="step"]',card)?.value==='1';
        let image=removed?'':(card.dataset.image||'');if(input.files?.[0])image=await uploadImage(input.files[0]);
        return {title:$('.step-title-input',card).value.trim(),text:$('.step-text-input',card).value.trim(),tip:$('.step-tip-input',card).value.trim(),image};
      }));
      const guide={...(existing||{}),id:existing?.id||`guide-${Date.now()}`,title:String(form.get('title')).trim(),description:String(form.get('description')).trim(),category:String(form.get('category')),difficulty:String(form.get('difficulty')),duration:Number(form.get('duration'))||30,materials:String(form.get('materials')).split(',').map(v=>v.trim()).filter(Boolean),outcome:String(form.get('outcome')).trim(),coverImage,steps,accent:existing?.accent||['violet','blue','green','amber'][db.guides.length%4],emoji:existing?.emoji||'',author:db.author.name,published:true};
      const response=await fetch('/api/guides',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(guide)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Не удалось сохранить инструкцию.');
      await loadData();state.page='author';state.editingId=null;state.draft=null;state.busy=false;toast(existing?'Инструкция сохранена':'Инструкция опубликована');
    }catch(error){state.busy=false;toast(error.message||'Не удалось сохранить инструкцию.');}
  }
});
function updateRemoveButtons(){const host=$('#steps-editor');if(!host)return;const cards=[...host.children];cards.forEach((card,i)=>{$('.remove-step',card).disabled=cards.length<=2;const controls=card.querySelectorAll('.step-controls button');if(controls[0])controls[0].disabled=i===0;if(controls[1])controls[1].disabled=i===cards.length-1;});}
function renumberSteps(){[...$('#steps-editor').children].forEach((card,i)=>{$('.step-editor-num',card).textContent=String(i+1).padStart(2,'0');$('.step-editor-heading b',card).textContent=`Шаг ${i+1}`;});updateRemoveButtons();}
async function loadData(){const [g,e,p]=await Promise.all([fetch('/api/guides'),fetch('/api/events'),fetch('/api/profile')]);db={guides:(await g.json()).guides,events:(await e.json()).events,author:(await p.json()).author};render();}
loadData().catch(()=>{app.innerHTML='<main class="server-error"><div class="brand-mark">s<span>.</span></div><h1>Не удалось подключиться</h1><p>Запустите приложение командой <code>npm start</code> в папке проекта.</p></main>';});
